def count_numbers(my_list):
	count_0=0
	count_1=0
	count_2=0
	count_3=0
	count_4=0
	count_5=0
	count_6=0
	count_7=0
	count_8=0
	count_9=0	
	new_list=[]
	for a in range(0,len(my_list)):
		if int(my_list[a])==0:
			count_0+=1
		elif int(my_list[a])==1:
			count_1+=1
		elif int(my_list[a])==2:
			count_2+=1
		elif int(my_list[a])==3:
			count_3+=1			
		elif int(my_list[a])==4:
			count_4+=1
		elif int(my_list[a])==5:
			count_5+=1
		elif int(my_list[a])==6:
			count_6+=1
		elif int(my_list[a])==7:
			count_7+=1
		elif int(my_list[a])==8:
			count_8+=1
		else:
			count_9+=1
	new_list=[count_0,count_1,count_2,count_3,count_4,count_5,count_6,count_7,count_8,count_9]
	return new_list
# 请不要更改此行以下的代码
