def get_min_plus_max(input_list):
    max=input_list[0]
    min=input_list[-1]
    for i in input_list:
        if i>max:
            max=i
        else:
            max=max
    for j in input_list:
        if j<min:
            min=j
        else:
            min=min
    return (max+min)



