def get_first_duplicate(instr) :
    res = ''
    pos = len(instr)
    po_dic = {}
    for i in range(len(instr)) :
        if instr[i] in po_dic :
            if pos > po_dic[instr[i]] :
                pos = po_dic[instr[i]]
                res = instr[i]
        else :
            po_dic[instr[i]] = i
    return res


