def palindrome(x, y):
    if x == 0 :
        return 0 
    elif x == 1:
        return (str(y) +' '+ '0'+' ' +str(y))
    else:
        left = str(y * x) + ' '
        mid= str(palindrome((x-1),y))
        right = ' ' + str(y * x)
    return(str(left)+str(mid)+str(right))

