def get_min_plus_max(list):
# 在这里编写代码
    sum_num = 0
    for num in list:
        sum_num +=num
    min_num = sum_num/len(list)
    for num in list:
        if num < min_num:
            min_num = num
    max_num = min_num
    for num in list:
        if num > max_num:
            max_num = num
    return int(max_num) + int(min_num)
