def get_min_plus_max(list):
# 在这里编写代码
    sum_num = 0
    for num in list:
        sum_num +=num
    for num in list:
        min_num = sum_num/len(list)
        if num < min_num:
            min_num = num
    for num in list:
        max_num = min_num
        if num > max_num:
            max_num = num
    return int(max_num) + int(min_num)
