def get_first_duplicate(input_str):
    # 创建一个字典，用于存储字符出现的次数
  char_count = {}
  # 遍历字符串中的每个字符
  for ch in input_str:
    # 如果字典中存在该字符，则更新字符的计数器
    if ch in char_count:
      char_count[ch] += 1
    # 否则，将该字符的计数器设置为1
    else:
      char_count[ch] = 1
  # 遍历字符串中的每个字符
  for ch in input_str:
    # 如果字符出现的次数大于1，则返回该字符
    if char_count[ch] > 1:
      return ch
  # 如果没有重复的字符，则返回空字符
  return ''
