position = {}
pos = []

def get_first_duplicate(input_str):
    for i in input_str:
        if i in position:
            pos.append(position[i])
        else:
            position[i] = input_str.find(str(i))
    if pos ==[]:
        return []
    else:
        return input_str[min(pos)]


