def get_min_plus_max(my_list):
    max_num = my_list[0]
    min_num = my_list[0]
    for i in my_list:
        if max_num <= i:
            max_num = i
    for j in my_list:
        if min_num >= j:
            min_num = j
    return max_num + min_num


