def count_numbers(input_list):
    cnt_0 = 0
    cnt_1 = 0
    cnt_2 = 0
    cnt_3 = 0
    cnt_4 = 0
    cnt_5 = 0
    cnt_6 = 0
    cnt_7 = 0
    cnt_8 = 0
    cnt_9 = 0
    for i in range(len(input_list)):
        if int(input_list[i]) == 0:
            cnt_0 += 1
        if int(input_list[i]) == 1:
            cnt_1 += 1
        if int(input_list[i]) == 2:
            cnt_2 += 1
        if int(input_list[i]) == 3:
            cnt_3 += 1
        if int(input_list[i]) == 4:
            cnt_4 += 1
        if int(input_list[i]) == 5:
            cnt_5 += 1
        if int(input_list[i]) == 6:
            cnt_6 += 1
        if int(input_list[i]) == 7:
            cnt_7 += 1
        if int(input_list[i]) == 8:
            cnt_8 += 1
        if int(input_list[i]) == 9:
            cnt_9 += 1
        new_list = [cnt_0]+[cnt_1]+[cnt_2]+[cnt_3]+[cnt_4]+[cnt_5]+[cnt_6]+[cnt_7]+[cnt_8]+[cnt_9]
    return new_list
