def get_min_plus_max(input_list):

    curr_num_max = input_list[0]
    for m in range(0,len(input_list)):
        if input_list[m] > curr_num_max:
            curr_num_max = input_list[m]

    curr_num_min = input_list[-1]
    for n in range(0,len(input_list)):
        if input_list[n] < curr_num_min:
            curr_num_min = input_list[n]

    return curr_num_max+curr_num_min

