position = {}

def get_first_duplicate(input_str):
    res = ''
    pos = -1

    for i in input_str:
        if i not in position:
            position[i] = -(len(input_str) + input_str.index(i))
        else:
            if position[i] < pos:
                res = i
                pos = position[i]
    return res

