def get_min_plus_max(my_list):
    max_num= my_list[0]
    for i in range(0,len(my_list)):
        if(max_num< my_list[i]):
            max_num = my_list[i]
    min_num = my_list[0]
    for i in range(0, len(my_list)):
        if (min_num > my_list[i]):
            min_num = my_list[i]
    return (max_num+ min_num)

