# 编写一个函数log_user(user_name)，其中的user_name是string。
# 如user_name已经在user_info里，该函数会给user_info内user_name对应的value加一；
# 否则在user_info里添加一项key为user_name, value为1。
def log_user(user_name):
    if user_name in user_info:
        user_info[user_name] = user_info[user_name] + 1
    else:
        user_info[user_name] = 1
# 第三步：编写一个函数print_user_log(user_name)，打印user_info中key为user_name对应的value
def print_user_log(user_name):
    if user_name in user_info:
        print(user_info[user_name])
    else:
        print(0)

