        if(input_list[i]=='6'):
            g+=1  
        if(input_list[i]=='7'):
            h+=1       
        if(input_list[i]=='8'):
            j+=1  
        if(input_list[i]=='9'):
            k+=1          
    new_list=[a,b,c,d,e,f,g,h,j,k]
    return new_list


