def get_first_duplicate(input_str):
    char_map = {}  # 用于存储字符及其出现的位置
    for i, char in enumerate(input_str):
        if char in char_map:
            return char
        else:
            char_map[char] = i

    # 如果整个字符串遍历完后仍然没有找到重复字符，则再次检查字典中的值
    for char, index in char_map.items():
        if input_str.count(char) > 1:
            return char

    return ""  # 如果没有重复字符，则返回空字符串
