def get_min_plus_max(x):
    max_num = x[0]
    small_num = x[0]
    for i in range(0,len(x)):
        if x[i] > max_num:
            max_num = x[i]
        if x[i] < small_num:
            small_num = x[i]
    return int(max_num) + int(small_num)

