def get_first_duplicate(input_str):
    res = ""
    pos = len(input_str)
    for item in input_str:
        if item not in position:
            position[item]=input_str.index(item) # {a:0},{a:0,b:1}

        elif position[item] < pos:
            res = item
            pos = position[item]
    return res

