def get_first_duplicate(input_str):
    position={}
    res=''
    pos=len(input_str)
    for i in range(0,len(input_str)):
        if not(input_str[i] in position):
            position[input_str[i]]=i
        elif position[input_str[i]]<pos:
            res=input_str[i]
            pos=i
    return res

