def get_min_plus_max(input_list):
    if len(input_list)==0:
        return
    max_num=input_list[0]
    for i in input_list:
        max_num=max(int(i),max_num)
    min_num=input_list[0]
    for j in input_list:
        min_num=min(int(j),min_num)
    return int(max_num+min_num)

