def get_min_plus_max(my_list):
    min_num = 0
    max_num = 0
    n = len(my_list)
    for i in range(1,n):
        if (my_list[min_num] < my_list[i]):
            min_num = min_num
        else:
            min_num = i
    for k in range(1,n):
        if (my_list[max_num] > my_list[k]):
            max_num = max_num
        else:
            max_num = k
    sum_num = my_list[min_num] + my_list[max_num]
    return sum_num


