def palindrome(my_list):
    # 如果列表的长度小于等于1，则肯定是回文
    if len(my_list) <= 1:
        return True

    # 去掉第一位和最后一位
    my_list.pop(0)
    my_list.pop(-1)
    if my_list == my_list[::-1]:
        return True
    else:
        return False
print(palindrome(temp_list))

