def get_min_plus_max(temp_list):
    max=int(temp_list[0])
    min=int(temp_list[0])
    for i in range(1,len(temp_list)):
        if(max<int(temp_list[i])):
            max=int(temp_list[i])
    for j in range(1,len(temp_list)):
        if(min>int(temp_list[j])):
            min=int(temp_list[j])
    return max+min

