# 2.用循环遍历my_str中的索引，用循环遍历my_str中的索引
# 3.如果两个列表中有元素重合，
# 4.进行测试
def get_first_duplicate(my_str):
    for i in range(0,len(my_str)):
        for j in range(i+1,len(my_str)):
            if my_str[i] == my_str[j]:
                return my_str[i]
        else:
            return ''
