def add_matrix(matrix_1, matrix_2):
    for i in range(0, len(matrix_1)):
        for j in range(0, len(matrix_2)):
            if i == j:
                for m in range(0, len(matrix_1[i])):
                    for n in range(0, len(matrix_2[j])):
                        if m == n:
                            matrix_1[i][m] = matrix_1[i][m]+matrix_2[j][n]
    return matrix_1  


