def palindrome(x, y):
    if x == 0:
        return 0
    if x == 1:
        return str(y) + " " + "0" + " " + str(y)
    else:
        left = str(x*y) + " "
        mid = str(palindrome((x-1)*y)) + " "
        right = str(x*y)
        return left + mid + right
