def palindrome(temp_list):
    del temp_list[0]
    del temp_list[len(temp_list) - 1]
    i = 0
    count = 1
    while i <= (len(temp_list)/2):
        if str(temp_list[i]) <= str(temp_list[len(temp_list) - 2 - i]):
            count = 1
            i += 1
        else:
            count = 0
            break
    if count == 1:
        return(True)
    else:
        return(False)

