def get_min_plus_max(input_list):
    min_number = input_list[1]
    max_number = input_list[1]
    for i in range(0, len(input_list)):
        if min_number > input_list[i]:
            min_number = input_list[i]
    for k in range(0, len(input_list)):
        if max_number < input_list[k]:
            max_number = input_list[k]
    sum_num = min_number + max_number
    return ("最大值"+str(max_number)+","+"最小值"+ str(min_number)+","+"返回"+str(sum_num)


