# 在这里编写代码
def palindrome(my_list):
    # 手动计算列表长度
    def calculate_length(lst):
        count = 0
        for _ in lst:
            count += 1
        return count

    # 递归检查是否回文的辅助函数
    def check_palindrome(start, end):
        # 终止条件：如果start >= end，则说明已经检查完
        if start >= end:
            return True
        # 如果两边的元素不同，返回 False
        if my_list[start] != my_list[end]:
            return False
        # 递归调用，继续向内部检查
        return check_palindrome(start + 1, end - 1)

    # 计算列表长度
    length = calculate_length(my_list)

    # 如果列表长度小于等于 2，去掉首尾后为空或单元素，直接返回 True
    if length <= 2:
        return True

    # 调用递归函数，从去掉首尾后的部分开始检查回文
    return check_palindrome(1, length - 2)




# 请不要更改此行以下的代码
print(palindrome(temp_list))

