def palindrome(x, y):
    if x == 0 :  #x是0, 不往两边展开
       return '0'
    if x == 1 :
        return str(y)+ ' '  + '0' + ' '  + str(y)

    else:
        left = x * y
        mid = palindrome(x - 1, y)
        right = x * y

        return str(left)+ ' ' + str(mid) + ' ' + str(right)



