def get_min_plus_max(my_list):

    max = my_list[0]
    min = my_list[0]
    for i in range(len(my_list)):
        if i+1 < len(my_list):
            if max < my_list[i+1]:
                max = my_list[i+1]
            elif min > my_list[i+1]:
                min = my_list[i+1]
            else:
                max = max
                min = min
        else:
            break

    number = max + min
    return number


