def add_matrix(input_list_1, input_list_2):
    x = 0
    m = 0
    n = 0
    while (x < len(input_list_1)):
        for i in range(0, len(input_list_1)):
            for j in range(0, len(input_list_1[i])):
                m = input_list_1[i][j]
        for a in range(0, len(input_list_2)):
            for b in range(0, len(input_list_2[a]):
                n = input_list_2[a][b]
        input_list_1 = [m + n]   

    return input_list_1           

