def get_min_plus_max(input_list):
    num_max=input_list[0]
    for i in input_list:
        if i>num_max:
            num_max=i
    num_min=input_list[0]
    for i in input_list:
        if i<num_min:
            num_min=i
    return (num_max + num_min)


